// Generated by scripts/sync-valuation.py from shared/valuation/cache.js as rp-valuation-cache.js; edit the shared source.
// Versioned, shared, frozen valuation cache. Pure model modules never import
// this file; only callers that explicitly opt into a same-realm cache do.
//
// The service is stored under Symbol.for('civ7.shared-valuation.cache.v1') so
// separately copied mods in the same JS realm share one instance. Contexts are
// isolated by player and save; changing either never reuses the other's values.
// Invalidation reasons are our own semantic entries, not engine event names.

export const SHARED_VALUATION_CACHE_VERSION = 1;
export const SHARED_VALUATION_CACHE_SYMBOL = Symbol.for('civ7.shared-valuation.cache.v1');

export const INVALIDATION_REASONS = Object.freeze({
  SNAPSHOT_CREATED: 'snapshot-created',
  TURN_ADVANCED: 'turn-advanced',
  RESOURCES_CHANGED: 'resources-changed',
  DEVELOPMENT_CENTER_CHANGED: 'development-center-changed',
  SETTLEMENT_COUNT_CHANGED: 'settlement-count-changed',
  SETTLEMENT_CAP_CHANGED: 'settlement-cap-changed',
  HAPPINESS_RULES_CHANGED: 'happiness-rules-changed',
  HORIZON_CONFIG_CHANGED: 'horizon-config-changed',
  SAVE_CHANGED: 'save-changed',
  PLAYER_CHANGED: 'player-changed'
});

const REASON_SET = new Set(Object.values(INVALIDATION_REASONS));

function deepFreeze(value, seen = new Set()) {
  if (value === null || typeof value !== 'object' || seen.has(value)) return value;
  seen.add(value);
  if (value instanceof Map || value instanceof Set) return value;
  for (const key of Object.keys(value)) deepFreeze(value[key], seen);
  return Object.freeze(value);
}

function contextKey(playerId, saveId) {
  return `${String(playerId)}\u0000${String(saveId)}`;
}


export class ValuationCacheStaleError extends Error {
  constructor(message = 'valuation cache entry is stale inside a batch; read/compute after the batch flush') {
    super(message);
    this.name = 'ValuationCacheStaleError';
    this.code = 'VALUATION_CACHE_STALE';
  }
}

function createService() {
  const stores = new Map();
  const generations = new Map();
  const stats = {
    hits: 0,
    misses: 0,
    computes: 0,
    sets: 0,
    deletes: 0,
    invalidations: 0,
    batchFlushes: 0,
    contextsCreated: 0
  };
  let batchDepth = 0;
  // contextKey -> array of invalidation descriptors
  const pending = new Map();

  function getStore(key) {
    if (!stores.has(key)) {
      stores.set(key, new Map());
      generations.set(key, 0);
      stats.contextsCreated++;
    }
    return stores.get(key);
  }

  function assertReason(reason) {
    if (!REASON_SET.has(reason)) throw new Error(`Unknown valuation invalidation reason: ${reason}`);
  }

  function scopeKey(scope, key) {
    return `${scope}\u0000${key}`;
  }

  function applyInvalidation(context, descriptor) {
    const store = stores.get(context);
    if (!store) return 0;
    let deleted = 0;
    if (descriptor.key === undefined) {
      for (const [storedKey, record] of store) {
        if (descriptor.scope !== undefined && record.scope !== descriptor.scope) continue;
        store.delete(storedKey);
        deleted++;
      }
    } else {
      const fullKey = scopeKey(descriptor.scope ?? 'valuation', descriptor.key);
      if (store.delete(fullKey)) deleted++;
    }
    if (deleted) {
      generations.set(context, (generations.get(context) || 0) + 1);
      stats.deletes += deleted;
    }
    return deleted;
  }

  function flushPending() {
    if (!pending.size) return;
    let touched = 0;
    for (const [context, descriptors] of pending) {
      for (const descriptor of descriptors) {
        if (applyInvalidation(context, descriptor) > 0) touched++;
      }
    }
    pending.clear();
    stats.batchFlushes++;
  }

  function invalidateContext(context, descriptor) {
    stats.invalidations++;
    if (batchDepth > 0) {
      if (!pending.has(context)) pending.set(context, []);
      pending.get(context).push(descriptor);
      return 0;
    }
    return applyInvalidation(context, descriptor);
  }

  function pendingCovers(context, scope, key) {
    const descriptors = pending.get(context);
    if (!descriptors) return false;
    return descriptors.some(descriptor => {
      if (descriptor.key !== undefined) {
        return String(descriptor.key) === String(key)
          && (descriptor.scope === undefined || descriptor.scope === scope);
      }
      return descriptor.scope === undefined || descriptor.scope === scope;
    });
  }

  function invalidateAll(descriptor) {
    stats.invalidations++;
    if (batchDepth > 0) {
      for (const context of stores.keys()) {
        if (!pending.has(context)) pending.set(context, []);
        pending.get(context).push(descriptor);
      }
      return 0;
    }
    let deleted = 0;
    for (const context of stores.keys()) deleted += applyInvalidation(context, descriptor);
    return deleted;
  }

  function makeContext(input = {}) {
    const {playerId, saveId, scope = 'valuation'} = input;
    if (playerId === undefined || playerId === null) throw new Error('valuation cache requires playerId for isolation');
    if (saveId === undefined || saveId === null || saveId === '') throw new Error('valuation cache requires saveId for isolation');
    const ctx = contextKey(playerId, saveId);
    getStore(ctx);
    const facade = {
      playerId,
      saveId,
      scope,
      contextKey: ctx,
      generation: () => generations.get(ctx) || 0,
      get(key) {
        if (pendingCovers(ctx, scope, key)) throw new ValuationCacheStaleError();
        const record = stores.get(ctx).get(scopeKey(scope, key));
        if (!record) { stats.misses++; return undefined; }
        stats.hits++;
        return record.value;
      },
      has(key) {
        if (pendingCovers(ctx, scope, key)) throw new ValuationCacheStaleError();
        return stores.get(ctx).has(scopeKey(scope, key));
      },
      set(key, value) {
        if (pendingCovers(ctx, scope, key)) throw new ValuationCacheStaleError();
        if (value === undefined) throw new Error('valuation cache cannot store undefined');
        stores.get(ctx).set(scopeKey(scope, key), deepFreeze({scope, value}));
        stats.sets++;
        return value;
      },
      getOrCompute(key, compute, {cacheable = () => true} = {}) {
        if (typeof compute !== 'function') throw new Error('valuation cache getOrCompute requires a function');
        if (typeof cacheable !== 'function') throw new Error('valuation cache cacheable must be a function');
        if (pendingCovers(ctx, scope, key)) throw new ValuationCacheStaleError();
        const fullKey = scopeKey(scope, key);
        const existing = stores.get(ctx).get(fullKey);
        if (existing) { stats.hits++; return existing.value; }
        stats.misses++;
        const value = compute(ctx, key);
        if (value === undefined) throw new Error('valuation cache compute returned undefined');
        stats.computes++;
        if (!cacheable(value)) return value;
        stores.get(ctx).set(fullKey, deepFreeze({scope, value}));
        return stores.get(ctx).get(fullKey).value;
      },
      invalidate(reason, {scope: targetScope = scope, key} = {}) {
        assertReason(reason);
        return invalidateContext(ctx, {reason, scope: targetScope, key});
      },
      invalidateAll(reason) {
        assertReason(reason);
        return invalidateContext(ctx, {reason});
      },
      batch(callback) {
        if (typeof callback !== 'function') throw new Error('valuation cache batch requires a function');
        batchDepth++;
        try {
          return callback();
        } finally {
          batchDepth--;
          if (batchDepth === 0) flushPending();
        }
      },
      keys() {
        return Object.freeze([...stores.get(ctx).entries()].map(([fullKey, record]) => ({scope: record.scope, key: fullKey.slice(record.scope.length + 1)})));
      },
      stats() {
        return Object.freeze({...stats, generation: generations.get(ctx) || 0});
      }
    };
    return Object.freeze(facade);
  }

  const handle = {
    version: SHARED_VALUATION_CACHE_VERSION,
    symbol: SHARED_VALUATION_CACHE_SYMBOL,
    context: makeContext,
    invalidate(reason, {playerId, saveId, scope, key} = {}) {
      assertReason(reason);
      if (playerId !== undefined && saveId !== undefined) {
        return invalidateContext(contextKey(playerId, saveId), {reason, scope, key});
      }
      return invalidateAll({reason, scope, key});
    },
    invalidateAll(reason) {
      assertReason(reason);
      return invalidateAll({reason});
    },
    batch(callback) {
      if (typeof callback !== 'function') throw new Error('valuation cache batch requires a function');
      batchDepth++;
      try {
        return callback();
      } finally {
        batchDepth--;
        if (batchDepth === 0) flushPending();
      }
    },
    stats() {
      return Object.freeze({...stats, contexts: stores.size, batchDepth});
    },
    keysFor(playerId, saveId) {
      if (playerId === undefined || saveId === undefined) throw new Error('keysFor requires playerId and saveId');
      const ctx = contextKey(playerId, saveId);
      const store = stores.get(ctx);
      if (!store) return Object.freeze([]);
      return Object.freeze([...store.entries()].map(([fullKey, record]) => ({scope: record.scope, key: fullKey.slice(record.scope.length + 1)})));
    },
    _flushForTests() {
      flushPending();
    }
  };
  return Object.freeze(handle);
}

export function getSharedValuationCache(globalObject = globalThis) {
  const existing = globalObject[SHARED_VALUATION_CACHE_SYMBOL];
  if (existing && existing.version === SHARED_VALUATION_CACHE_VERSION && typeof existing.context === 'function' && typeof existing.batch === 'function') {
    return existing;
  }
  const service = createService();
  try {
    Object.defineProperty(globalObject, SHARED_VALUATION_CACHE_SYMBOL, {
      value: service,
      writable: false,
      configurable: false,
      enumerable: false
    });
  } catch (error) {
    throw new Error(`Unable to install shared valuation cache: ${error.message}`);
  }
  return service;
}

export function createIsolatedValuationCache() {
  return createService();
}

export {deepFreeze};
